  height: 2px; background: var(--accent); border-radius: 1px;
}

/* ===== Cards ===== */
.card {
  background: var(--bg-card); border: 1px solid var(--border);
  border-radius: var(--radius-lg); overflow: hidden;
}
.card__header {
  padding: 14px 18px; border-bottom: 1px solid var(--border);
  display: flex; align-items: center; justify-content: space-between;
}
.card__title { font-size: 0.95rem; font-weight: 600; }
.card__body { padding: 18px; }

/* ===== Tables ===== */
.table-wrap { overflow-x: auto; }
table { width: 100%; border-collapse: collapse; }
th, td { padding: 10px 14px; text-align: left; white-space: nowrap; }
th {
  font-size: 0.8rem; font-weight: 500; color: var(--text-secondary);
  text-transform: uppercase; letter-spacing: 0.5px;
  border-bottom: 1px solid var(--border);
}
td { font-size: 0.9rem; border-bottom: 1px solid var(--border); }
tr:last-child td { border-bottom: none; }
tr:hover td { background: var(--bg-hover); }

/* ===== Badge ===== */
.badge {
  display: inline-flex; align-items: center; gap: 4px;
  padding: 2px 8px; border-radius: 4px; font-size: 0.8rem; font-weight: 600;
}
.badge--positive { color: var(--positive); background: var(--positive-bg); }
.badge--negative { color: var(--negative); background: var(--negative-bg); }
.badge--blue { color: var(--accent); background: rgba(41,98,255,0.12); }
.badge--gold { color: #FFD54F; background: rgba(255,213,79,0.12); }
.badge--platinum { color: #B0BEC5; background: rgba(176,190,197,0.12); }

/* ===== Star Rating ===== */
.stars { color: #FFD54F; letter-spacing: 1px; }
.stars .empty { color: var(--border-light); }

/* ===== Ticker ===== */
.ticker { font-weight: 600; color: var(--text-primary); }
.ticker-name { color: var(--text-secondary); font-size: 0.82rem; }

/* ===== Sparkline ===== */
.sparkline { width: 80px; height: 28px; }

/* ===== Section ===== */
.section { padding: 32px 24px; max-width: 1440px; margin: 0 auto; }
.section__title { font-size: 1.15rem; font-weight: 600; margin-bottom: 16px; }

/* ===== Footer ===== */
.footer {
  background: var(--bg-secondary); border-top: 1px solid var(--border);
  padding: 48px 24px 24px; margin-top: 48px;
}
.footer__grid {
  display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
  gap: 32px; max-width: 1440px; margin: 0 auto;
}
.footer__col h4 {
  font-size: 0.85rem; font-weight: 600; color: var(--text-secondary);
  text-transform: uppercase; letter-spacing: 0.5px; margin-bottom: 14px;
}
.footer__col a {
  display: block; color: var(--text-secondary); font-size: 0.9rem;
  padding: 3px 0; transition: color .15s;
}
.footer__col a:hover { color: var(--text-primary); text-decoration: none; }
.footer__bottom {
  max-width: 1440px; margin: 32px auto 0;
  padding-top: 24px; border-top: 1px solid var(--border);
  display: flex; justify-content: space-between; align-items: center;
  font-size: 0.82rem; color: var(--text-muted);
}
.footer__logo { font-weight: 700; color: #fff; }

/* ===== Layout helpers ===== */
.grid-2 { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; }
.grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px; }
.grid-4 { display: grid; grid-template-columns: repeat(4, 1fr); gap: 20px; }
.flex-between { display: flex; justify-content: space-between; align-items: center; }
.flex-center { display: flex; align-items: center; gap: 8px; }
.gap-8 { gap: 8px; }
.gap-16 { gap: 16px; }
.gap-24 { gap: 24px; }

/* ===== Change colors ===== */
.positive { color: var(--positive); }
.negative { color: var(--negative); }
.muted { color: var(--text-secondary); }

/* ===== Tag ===== */
.tag {
  display: inline-block; padding: 3px 10px; border-radius: 4px;
  font-size: 0.78rem; font-weight: 500;
  background: var(--bg-hover); color: var(--text-secondary);
}

/* ===== Toggle Switch ===== */
.toggle { display: inline-flex; align-items: center; gap: 8px; cursor: pointer; }
.toggle input { display: none; }
.toggle__slider {
  width: 36px; height: 20px; border-radius: 10px;
  background: var(--border-light); position: relative; transition: background .2s;
}
.toggle__slider::after {
  content: ''; position: absolute; top: 2px; left: 2px;
  width: 16px; height: 16px; border-radius: 50%;
  background: var(--text-secondary); transition: all .2s;
}
.toggle input:checked + .toggle__slider { background: var(--accent); }
.toggle input:checked + .toggle__slider::after { left: 18px; background: #fff; }

/* ===== Pagination ===== */
.pagination {
  display: flex; align-items: center; justify-content: center; gap: 6px;
  padding: 24px 0;
}
.pagination a, .pagination span {
  display: inline-flex; align-items: center; justify-content: center;
  min-width: 36px; height: 36px; border-radius: var(--radius);
  font-size: 0.9rem; font-weight: 500;
  color: var(--text-secondary); border: 1px solid var(--border);
  transition: all .15s; text-decoration: none;
}
.pagination a:hover, .pagination span.active {
  color: var(--accent); border-color: var(--accent);
  text-decoration: none;
}

/* ===== Stat Card ===== */
.stat-card {
  padding: 16px; border-radius: var(--radius);
  background: var(--bg-card); border: 1px solid var(--border);
}
.stat-card__label { font-size: 0.8rem; color: var(--text-secondary); margin-bottom: 4px; }
.stat-card__value { font-size: 1.25rem; font-weight: 700; }
.stat-card__sub { font-size: 0.82rem; color: var(--text-secondary); margin-top: 2px; }

/* ===== Responsive ===== */
@media (max-width: 1024px) {
  .grid-4 { grid-template-columns: repeat(2, 1fr); }
  .grid-3 { grid-template-columns: 1fr 1fr; }
}
@media (max-width: 768px) {
  .nav__links { display: none; }
  .grid-2, .grid-3, .grid-4 { grid-template-columns: 1fr; }
  .section { padding: 20px 16px; }
  .footer__grid { grid-template-columns: repeat(2, 1fr); }
}

